# Restore Classic File Explorer (Windows 10 Style) Write-Host "Restoring classic File Explorer with ribbon interface..." -ForegroundColor Cyan # Disable Windows 11 new File Explorer command bar Set-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Shell Extensions\Blocked" -Name "{e2bf4bde-6dbf-4b1b-867e-5b7d8a9be425}" -Value "" -Force -ErrorAction SilentlyContinue # Enable classic ribbon Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "UseCompactMode" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue # Show file extensions Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "HideFileExt" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue # Show hidden files Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" -Name "Hidden" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue # Restart Explorer to apply changes Stop-Process -Name explorer -Force -ErrorAction SilentlyContinue Start-Sleep -Seconds 2 Start-Process explorer Write-Host "Classic File Explorer has been restored." -ForegroundColor Green